import type { CodeFile } from "@/app/types";

/** Served from `public/vendor/pyodide/` (generated by `bun run vendor:pyodide`). */
export const PYTHON_WORKER_URL = "/vendor/pyodide/python-worker.js";

/** Time allowed for the program after Pyodide is ready. Loading Pyodide is not counted. */
export const PYTHON_RUN_TIMEOUT_MS = 10_000;
/** Pyodide plus pandas and matplotlib is about 30MB on the first run. */
export const PYTHON_LOAD_TIMEOUT_MS = 120_000;
/**
 * Characters of output kept per run. python-worker.js stops sending at the same number, so a print
 * loop cannot flood the page; keep the two in step.
 */
export const PYTHON_MAX_OUTPUT_LENGTH = 100_000;
/** Figures (matplotlib PNGs) kept per run, and the size of one. python-worker.js uses the same numbers. */
export const PYTHON_MAX_FIGURES = 20;
export const PYTHON_MAX_FIGURE_BYTES = 5_000_000;
/** Run first when present; otherwise the first file the exercise lists. */
export const PYTHON_ENTRY_FILENAME = "main.py";

export type PythonStream = "stdout" | "stderr";

export interface PythonOutputChunk {
  stream: PythonStream;
  text: string;
}

export type PythonWorkerMessage =
  | { type: "packages"; names: string[] }
  | { type: "ready" }
  | { type: "figure"; png: Uint8Array<ArrayBuffer> }
  | { type: "figure-skipped" }
  | { type: "output"; stream: PythonStream; text: string }
  | { type: "truncated" }
  | { type: "done" }
  | { type: "fatal"; message: string };

export interface PythonRunFile {
  filename: string;
  content: string;
}

export type PythonRunPlan =
  | { ok: true; entry: string; files: PythonRunFile[] }
  | { ok: false; message: string };

/**
 * Files are written side by side in the worker's working directory, so a name must be a plain file
 * name: a path could climb out of it or collide with the files Pyodide itself loads.
 */
function isPlainFilename(name: string): boolean {
  return name !== "." && name !== ".." && !/[/\\\0]/.test(name);
}

/**
 * What the worker writes and which file it runs. A single-file submission can arrive without a
 * filename; it runs as main.py so tracebacks still name a file.
 */
export function preparePythonRun(
  files: readonly Pick<CodeFile, "filename" | "content">[]
): PythonRunPlan {
  if (files.length === 0) {
    return { ok: false, message: "実行する Python のコードがありません" };
  }
  const prepared: PythonRunFile[] = [];
  const seen = new Set<string>();
  for (const file of files) {
    const filename = file.filename.trim() || (files.length === 1 ? PYTHON_ENTRY_FILENAME : "");
    if (!filename || !isPlainFilename(filename)) {
      return {
        ok: false,
        message: `ファイル名「${filename}」では実行できません（フォルダを含まない名前にしてください）`,
      };
    }
    if (seen.has(filename)) {
      return { ok: false, message: `同じ名前のファイル「${filename}」が複数あります` };
    }
    seen.add(filename);
    prepared.push({ filename, content: file.content });
  }
  if (prepared.every((file) => file.content.trim() === "")) {
    return { ok: false, message: "実行する Python のコードがありません" };
  }
  const entry = seen.has(PYTHON_ENTRY_FILENAME) ? PYTHON_ENTRY_FILENAME : prepared[0].filename;
  return { ok: true, entry, files: prepared };
}

/**
 * Adds output in arrival order, joining runs of the same stream so the page renders a few spans
 * instead of one per print. Returns whether the limit cut the text.
 */
export function appendPythonOutput(
  chunks: PythonOutputChunk[],
  stream: PythonStream,
  text: string
): { chunks: PythonOutputChunk[]; truncated: boolean } {
  const used = chunks.reduce((sum, chunk) => sum + chunk.text.length, 0);
  const room = PYTHON_MAX_OUTPUT_LENGTH - used;
  if (room <= 0) {
    return { chunks, truncated: text.length > 0 };
  }
  const kept = text.length > room ? text.slice(0, room) : text;
  if (kept === "") {
    return { chunks, truncated: false };
  }
  const last = chunks[chunks.length - 1];
  const next =
    last && last.stream === stream
      ? [...chunks.slice(0, -1), { stream, text: last.text + kept }]
      : [...chunks, { stream, text: kept }];
  return { chunks: next, truncated: kept.length < text.length };
}

/**
 * The worker is a same-origin file, but a message is still checked before it reaches the page: only
 * the known shapes get through.
 */
export function acceptPythonWorkerMessage(raw: unknown): PythonWorkerMessage | null {
  const data = raw as Record<string, unknown> | null;
  if (!data || typeof data !== "object") {
    return null;
  }
  switch (data.type) {
    case "ready":
    case "truncated":
    case "figure-skipped":
    case "done":
      return { type: data.type };
    case "packages":
      return Array.isArray(data.names) && data.names.every((name) => typeof name === "string")
        ? { type: "packages", names: data.names as string[] }
        : null;
    case "figure":
      return isPng(data.png) ? { type: "figure", png: data.png } : null;
    case "output":
      return (data.stream === "stdout" || data.stream === "stderr") && typeof data.text === "string"
        ? { type: "output", stream: data.stream, text: data.text }
        : null;
    case "fatal":
      return typeof data.message === "string" ? { type: "fatal", message: data.message } : null;
    default:
      return null;
  }
}

const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];

/** Only a PNG within the size limit is shown; the page turns it into an image, never into markup. */
function isPng(value: unknown): value is Uint8Array<ArrayBuffer> {
  return (
    value instanceof Uint8Array &&
    value.buffer instanceof ArrayBuffer &&
    value.byteLength > PNG_SIGNATURE.length &&
    value.byteLength <= PYTHON_MAX_FIGURE_BYTES &&
    PNG_SIGNATURE.every((byte, index) => value[index] === byte)
  );
}
